{
  "name": "LEONI光纤开关",
  "name_en": "LEONI Fiber Switch",
  "manufacturer": "LEONI",
  "description": "一种多通道光纤切换设备，用于在多个光纤通道之间选择当前连通的通路，常用于光学实验、光路切换和自动化测试系统中的信号路由。",
  "description_en": "A multi-channel fiber switch used to select the active connection among multiple fiber channels. It is commonly used in optical experiments, light-path switching, and automated test setups for signal routing.",
  "tag_hints": [
    "fiber switch",
    "optical routing",
    "multi-channel switching",
    "photonics experiment",
    "automated optical testing",
    "channel selection"
  ],
  "actions": [
    {
      "action_name": "auto-set_active_channel",
      "description": "设置当前活动通道。",
      "description_en": "Set the active channel."
    },
    {
      "action_name": "auto-ping",
      "description": "检查设备是否响应通信。",
      "description_en": "Check whether the device is responding to communication."
    },
    {
      "action_name": "auto-close",
      "description": "关闭与设备的通信连接。",
      "description_en": "Close the communication connection to the device."
    },
    {
      "action_name": "auto-get_num_channels",
      "description": "获取通道总数。",
      "description_en": "Get the total number of channels."
    },
    {
      "action_name": "auto-get_active_channel",
      "description": "获取当前活动通道。",
      "description_en": "Get the active channel."
    },
    {
      "action_name": "auto-get_firmware_rev",
      "description": "获取固件版本。",
      "description_en": "Get the firmware revision."
    }
  ]
}

